using Forge.LiveDirector.Authoring;
using Forge.Network.Authoring;
using Forge.Network.Operations;
using Forge.Network.Sessions;
namespace Forge.Mcp.LiveDirector; public sealed record LiveDirectorNarrativePlan(Guid PlanId, long BaseRevision, string ActorId, NetworkRole Role, NetworkAuthorityScope Scope, LiveDirectorNarrativeProfile Candidate); public sealed class LiveDirectorNarrativeAgentService { private readonly LiveDirectorNarrativeHistory h; private LiveDirectorNarrativePlan? plan; public LiveDirectorNarrativeAgentService() : this(LiveDirectorNarrativeProfile.CreateDefault("mcp:r130")) { } public LiveDirectorNarrativeAgentService(LiveDirectorNarrativeProfile p) => h = new(p); public LiveDirectorNarrativeProfile Get(string? search = null) { if (!string.IsNullOrWhiteSpace(search) && !"quest encounter".Contains(search, StringComparison.OrdinalIgnoreCase)) throw new KeyNotFoundException("LIVE_NARRATIVE_NOT_FOUND"); return h.Current; } public LiveDirectorNarrativeResult Plan(LiveDirectorNarrativePlan q) { if (q.Scope != NetworkAuthorityScope.Server) return new(false, false, h.Current, [new("LIVE_NARRATIVE_SCOPE_INVALID", "/liveDirector/narrative/authorityScope", "Server required.", q.Candidate.Id)], "none", "rejected"); var r = h.Execute(new(q.PlanId, 1, q.Candidate.Provenance, q.BaseRevision, q.ActorId, q.Role, false, q.Candidate)); if (r.Succeeded) plan = q; return r; } public LiveDirectorNarrativeResult Apply(Guid id) { if (plan is null || plan.PlanId != id) return new(false, false, h.Current, [new("LIVE_NARRATIVE_PLAN_UNKNOWN", "/liveDirector/narrative/planId", "Unknown.")], "none", "rejected"); var q = plan; plan = null; return h.Execute(new(q.PlanId, 1, q.Candidate.Provenance, q.BaseRevision, q.ActorId, q.Role, true, q.Candidate)); } public LiveDirectorNarrativeResult Revert(string actor, NetworkRole role) => h.Undo(actor, role); }
